// Typed access to src/data/snapshot.json, generated by scripts/snapshot-labs.mjs.
import snapshot from "./snapshot.json";

export interface Task {
  id: number;
  filename: string;
  title: string;
  marker_complete: boolean;
  source: string;
  output: string | null;
}

export interface Lab {
  slug: string;
  title: string;
  directory: string;
  tasks: Task[];
}

export const labs: Lab[] = snapshot.labs;
